defmodule Readability.URLTest do
  use ExUnit.Case, async: true

  alias Readability.URL

  # Generated by scripts/gen_url_cases.js from Node's `URL`.
  @fixture Path.expand("../fixtures/url_cases.json", __DIR__)
  @external_resource @fixture

  # Edge cases where we knowingly differ from Node: Node 24 (Ada) resolves some references that
  # contain "#" against a base with an opaque path, e.g. `new URL("a#", "about:blank")` gives
  # "about:blank/a#" while `new URL("a", "about:blank")` throws. The URL Standard says failure
  # for both, and so do we. Readability.js only resolves against the document's http(s) URL.
  defp known_difference?({input, base, {:ok, _}, :error}) when is_binary(base) do
    {:ok, %URL{path: path}} = URL.parse_base(base)
    match?({:opaque, _}, path) and String.contains?(input, "#") and not String.starts_with?(input, "#")
  end

  defp known_difference?(_), do: false

  defp cases do
    data = @fixture |> File.read!() |> :json.decode()

    for group <- ["pages", "edge"] do
      %{"resolve" => resolve, "parse" => parse} = data[group]

      resolve_cases =
        for {base, list} <- resolve, [input, href] <- list do
          {input, base, expected(input, href)}
        end

      parse_cases = for [input, href] <- parse, do: {input, nil, expected(input, href)}
      {group, resolve_cases ++ parse_cases}
    end
    |> Map.new()
  end

  defp expected(input, true), do: {:ok, input}
  defp expected(_input, :null), do: :error
  defp expected(_input, href), do: {:ok, href}

  defp disagreements(cases) do
    for {input, base, expected} <- cases,
        actual = safe_resolve(input, base),
        actual != expected,
        do: {input, base, expected, actual}
  end

  defp safe_resolve(input, base) do
    URL.resolve(input, base)
  rescue
    e -> {:raised, Exception.message(e)}
  end

  test "agrees with Node's URL on every URL in the test pages" do
    cases = cases()["pages"]
    assert length(cases) > 20_000
    assert disagreements(cases) == []
  end

  test "agrees with Node's URL on edge cases, except known Node quirks" do
    cases = cases()["edge"]
    assert length(cases) > 2500
    {known, bad} = cases |> disagreements() |> Enum.split_with(&known_difference?/1)
    assert bad == []
    assert length(known) < 50
  end

  # Readability.js's `new URL` converts these hosts (IDNA, IPv4 parsing) or rejects them.
  test "domains are percent-decoded and lower-cased, otherwise kept as written" do
    for {input, expected} <- [
          {"http://MÜNCHEN.de/a/../b", {:ok, "http://mÜnchen.de/b"}},
          {"https://%C3%A4.com", {:ok, "https://ä.com/"}},
          {"https://Ex%41mple.com", {:ok, "https://example.com/"}},
          {"https://xn--a-wbb.com", {:ok, "https://xn--a-wbb.com/"}},
          {"http://0x7F.1/", {:ok, "http://0x7f.1/"}},
          {"http://256.0.0.1/", {:ok, "http://256.0.0.1/"}},
          {"https://example.com%80/", :error},
          {"https://ex%25ample.com/", :error},
          {"https://ex%00ample.com/", :error},
          {"https://%2F/", :error}
        ] do
      assert URL.resolve(input, nil) == expected, inspect(input)
    end

    assert URL.resolve("../c?d", "http://日本語.jp/a/b") == {:ok, "http://日本語.jp/c?d"}
  end

  test "IPv6: \"::\" stands for at least one piece" do
    for {input, expected} <- [
          {"http://[1:2:3:4:5:6:7:8::]/", :error},
          {"http://[::1:2:3:4:5:6:7:8]/", :error},
          {"http://[1:2:3:4::5:6:7:8]/", :error},
          {"http://[::1:2:3:4:5:6:1.2.3.4]/", :error},
          {"http://[1:2:3:4:5:6:7::]/", {:ok, "http://[1:2:3:4:5:6:7:0]/"}},
          {"http://[::2:3:4:5:6:7:8]/", {:ok, "http://[0:2:3:4:5:6:7:8]/"}},
          {"http://[1:2:3::5:6:7:8]/", {:ok, "http://[1:2:3:0:5:6:7:8]/"}},
          {"http://[::1:2:3:4:5:1.2.3.4]/", {:ok, "http://[0:1:2:3:4:5:102:304]/"}},
          {"http://[::1.2.3.04]/", :error},
          {"http://[fe80::1%25eth0]/", :error},
          {"http://[fe80::1%eth0]/", :error},
          {"http://[0001:0:0:0:0:0:0:A]/", {:ok, "http://[1::a]/"}}
        ] do
      assert URL.resolve(input, nil) == expected, input
    end
  end

  test "url?/1" do
    assert URL.url?("http://example.com/a")
    assert URL.url?("mailto:x@example.com")
    refute URL.url?("/relative")
    refute URL.url?("John Smith")
    refute URL.url?("http://")
  end

  test "base_uri/2 follows JSDOMParser" do
    doc = "http://fakehost/test/page.html"
    assert URL.base_uri(doc, nil) == doc
    assert URL.base_uri(doc, "") == doc
    assert URL.base_uri(doc, "/foo/bar/") == "http://fakehost/foo/bar/"
    assert URL.base_uri(doc, "http://[") == doc
  end

  test "absolutizer/2 keeps hash links only when base and document URI are equal" do
    doc = "http://fakehost/test/page.html"
    same = URL.absolutizer(doc, doc)
    assert same.("#top") == "#top"
    assert same.("foo bar.html") == "http://fakehost/test/foo%20bar.html"
    assert same.("http://[") == "http://["

    based = URL.absolutizer("http://fakehost/base/", doc)
    assert based.("#top") == "http://fakehost/base/#top"
    assert based.("../x") == "http://fakehost/x"

    assert URL.absolutizer("not a url", "not a url").("x") == "x"
  end

  test "absolutize_srcset/2 matches Readability.js's srcsetUrl replace" do
    abs = URL.absolutizer("http://fakehost/base/", "http://fakehost/test/page.html")

    assert URL.absolutize_srcset("a.jpg 1x, b.jpg 2x", abs) ==
             "http://fakehost/base/a.jpg 1x, http://fakehost/base/b.jpg 2x"

    assert URL.absolutize_srcset("a.jpg 100w,b.jpg 200w", abs) ==
             "http://fakehost/base/a.jpg 100w,http://fakehost/base/b.jpg 200w"

    # \S+ is greedy: commas without descriptors stay inside one URL
    assert URL.absolutize_srcset("a.jpg,b.jpg", abs) == "http://fakehost/base/a.jpg,b.jpg"
    # a URL followed by something that is not a descriptor or a comma is left alone
    assert URL.absolutize_srcset("a b", abs) == "a http://fakehost/base/b"
  end

  test "javascript?/1" do
    assert URL.javascript?("javascript:void(0)")
    refute URL.javascript?("JavaScript:void(0)")
    refute URL.javascript?(" javascript:void(0)")
  end
end
